class BookWriteSerializer(serializers.ModelSerializer):
    """سریالایزر نوشتن — ورودی ساده."""
    categories = serializers.SlugRelatedField(
        many=True,
        slug_field="slug",
        queryset=Category.objects.all(),
        required=False,
    )

    class Meta:
        model = Book
        fields = [
            "id", "title", "subtitle", "description",
            "author", "categories",
            "isbn", "cover", "document",
            "price", "discount_price",
            "published_at", "pages", "language", "publisher",
            "stock", "total_copies",
            "is_published", "is_featured",
        ]
        read_only_fields = ["id"]

    def validate_isbn(self, value):
        clean = value.replace("-", "").strip()
        if not clean.isdigit() or len(clean) not in (10, 13):
            raise serializers.ValidationError("ISBN باید ۱۰ یا ۱۳ رقم عددی باشد.")
        return clean

    def validate_price(self, value):
        if value < 0:
            raise serializers.ValidationError("قیمت نمی‌تواند منفی باشد.")
        return value

    def validate(self, attrs):
        price = attrs.get("price")
        discount = attrs.get("discount_price")
        if discount is not None and price is not None and discount >= price:
            raise serializers.ValidationError(
                {"discount_price": "قیمت تخفیف باید کمتر از قیمت اصلی باشد."}
            )
        if "stock" in attrs and "total_copies" in attrs:
            if attrs["stock"] > attrs["total_copies"]:
                raise serializers.ValidationError(
                    {"stock": "موجودی نمی‌تواند بیشتر از کل نسخه‌ها باشد."}
                )
        return attrs

    def to_internal_value(self, data):
        # نرمال‌سازی ISBN
        data = data.copy() if hasattr(data, "copy") else data
        return super().to_internal_value(data)

