from django.db.models import Avg, Count, Q, Prefetch
from .models import Book, Author, Category


def book_list_queryset():
    """QuerySet بهینه برای لیست کتاب‌ها."""
    return (
        Book.objects.filter(is_published=True, is_deleted=False)
        .select_related("author")
        .prefetch_related("categories")
        .annotate(
            average_rating=Avg("reviews__rating", filter=Q(reviews__is_approved=True)),
            reviews_count=Count("reviews", filter=Q(reviews__is_approved=True), distinct=True),
        )
    )


def book_detail_queryset():
    """QuerySet بهینه برای جزئیات کتاب."""
    return (
        Book.objects
        .select_related("author", "owner")
        .prefetch_related("categories")
        .annotate(
            average_rating=Avg("reviews__rating", filter=Q(reviews__is_approved=True)),
            reviews_count=Count("reviews", filter=Q(reviews__is_approved=True), distinct=True),
        )
    )


def author_list_queryset():
    return (
        Author.objects.filter(is_deleted=False)
        .annotate(books_count=Count("books", filter=Q(books__is_published=True, books__is_deleted=False), distinct=True))
    )


def category_list_queryset():
    return (
        Category.objects.filter(is_deleted=False)
        .select_related("parent")
        .annotate(books_count=Count("books", filter=Q(books__is_published=True, books__is_deleted=False), distinct=True))
    )

from rest_framework.permissions import BasePermission, SAFE_METHODS


class IsAuthorOrStaffOrReadOnly(BasePermission):
    """
    خواندن برای همه.
    نوشتن فقط برای نویسنده کتاب یا کارمند.
    """
    message = "فقط نویسنده یا کارمند می‌تواند این کتاب را تغییر دهد."

    def has_permission(self, request, view):
        if request.method in SAFE_METHODS:
            return True
        return request.user.is_authenticated

    def has_object_permission(self, request, view, obj):
        if request.method in SAFE_METHODS:
            return True
        if request.user.is_staff:
            return True
        return obj.owner == request.user

