class AuthorViewSet(viewsets.ModelViewSet):
    permission_classes = [IsAdminOrReadOnly]
    pagination_class = StandardPagination
    lookup_field = "slug"
    filter_backends = [DjangoFilterBackend, filters.SearchFilter, filters.OrderingFilter]
    filterset_class = AuthorFilter
    search_fields = ["full_name", "bio"]
    ordering_fields = ["full_name", "created_at"]
    ordering = ["full_name"]

    def get_queryset(self):
        return author_list_queryset()

    def get_serializer_class(self):
        if self.action == "list":
            return AuthorListSerializer
        return AuthorDetailSerializer

    @action(detail=True, methods=["get"])
    def books(self, request, slug=None):
        """کتاب‌های این نویسنده."""
        author = self.get_object()
        qs = author.books.filter(is_published=True, is_deleted=False).select_related("author")
        page = self.paginate_queryset(qs)
        if page is not None:
            serializer = BookListSerializer(page, many=True, context={"request": request})
            return self.get_paginated_response(serializer.data)
        serializer = BookListSerializer(qs, many=True, context={"request": request})
        return Response(serializer.data)


