class BookViewSet(viewsets.ModelViewSet):
    """ViewSet کتاب با فیلتر، جستجو، مرتب‌سازی، آمار و آپلود."""
    permission_classes = [IsAuthenticatedOrReadOnly, IsAuthorOrStaffOrReadOnly]
    pagination_class = StandardPagination
    lookup_field = "slug"
    filter_backends = [DjangoFilterBackend, filters.SearchFilter, filters.OrderingFilter]
    filterset_class = BookFilter
    search_fields = ["title", "subtitle", "description", "isbn", "author__full_name"]
    ordering_fields = ["price", "published_at", "created_at", "views_count", "loans_count"]
    ordering = ["-created_at"]

    def get_queryset(self):
        if self.action == "list":
            return book_list_queryset()
        return book_detail_queryset()

    def get_serializer_class(self):
        if self.action == "list":
            return BookListSerializer
        if self.action in ("create", "update", "partial_update"):
            return BookWriteSerializer
        return BookDetailSerializer

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

    def retrieve(self, request, *args, **kwargs):
        """دریافت جزئیات + افزایش views_count."""
        instance = self.get_object()
        # افزایش views_count با F برای جلوگیری از race condition
        from django.db.models import F
        Book.objects.filter(pk=instance.pk).update(views_count=F("views_count") + 1)
        serializer = self.get_serializer(instance)
        return Response(serializer.data)

    @action(detail=False, methods=["get"])
    def featured(self, request):
        """کتاب‌های ویژه."""
        qs = book_list_queryset().filter(is_featured=True)[:10]
        serializer = BookListSerializer(qs, many=True, context={"request": request})
        return Response(serializer.data)

    @action(detail=False, methods=["get"])
    def newest(self, request):
        """جدیدترین کتاب‌ها."""
        qs = book_list_queryset().order_by("-created_at")[:10]
        serializer = BookListSerializer(qs, many=True, context={"request": request})
        return Response(serializer.data)

    @action(detail=False, methods=["get"])
    def popular(self, request):
        """محبوب‌ترین کتاب‌ها بر اساس loans_count."""
        qs = book_list_queryset().order_by("-loans_count")[:10]
        serializer = BookListSerializer(qs, many=True, context={"request": request})
        return Response(serializer.data)

    @action(detail=True, methods=["post"], permission_classes=[IsAuthenticatedOrReadOnly])
    def increment_view(self, request, slug=None):
        """افزایش views_count."""
        from django.db.models import F
        Book.objects.filter(slug=slug).update(views_count=F("views_count") + 1)
        return Response({"detail": "ok"})

