@pytest.mark.django_db
class TestBookCreate:
    url = "/api/books/"

    def test_anonymous_cannot_create(self, api_client):
        response = api_client.post(self.url, {}, format="json")
        assert response.status_code == 401

    def test_authenticated_can_create(self, api_client, user, author):
        api_client.force_authenticate(user=user)
        payload = {
            "title": "New Book",
            "author": str(author.id),
            "isbn": "9780000000002",
            "price": "29.99",
            "published_at": "2021-01-01",
        }
        response = api_client.post(self.url, payload, format="json")
        assert response.status_code == 201
        assert Book.objects.filter(isbn="9780000000002").exists()

    def test_invalid_isbn(self, api_client, user, author):
        api_client.force_authenticate(user=user)
        payload = {
            "title": "New Book",
            "author": str(author.id),
            "isbn": "invalid",
            "price": "10.00",
            "published_at": "2021-01-01",
        }
        response = api_client.post(self.url, payload, format="json")
        assert response.status_code == 400


